1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.List;
8	import net.officefloor.hq.app.Audit;
9	import net.officefloor.hq.app.holiday.HolidayService;
10	import net.officefloor.hq.app.person.Person;
11	import net.officefloor.hq.app.period.PeriodService;
12	import net.officefloor.hq.app.person.PersonRepository;
13	import net.officefloor.hq.app.person.WatchService;
14	import net.officefloor.hq.app.role.Role;
15	import net.officefloor.hq.app.role.RoleService;
16	import net.officefloor.hq.app.rollup.Rollups;
17	import net.officefloor.hq.app.sheet.Sheet;
18	import net.officefloor.hq.app.sheet.SheetService;
19	import net.officefloor.hq.app.sheet.TodayChanged;
20	import net.officefloor.hq.app.voidreason.VoidReasonService;
21	import org.springframework.context.event.EventListener;
22	import org.springframework.http.HttpStatus;
23	import org.springframework.stereotype.Service;
24	import org.springframework.transaction.annotation.Transactional;
25	import org.springframework.web.server.ResponseStatusException;
26	
27	/** The claims people on a sheet make: listed, added, edited and moved through their statuses. */
28	@Service
29	public class ClaimService {
30	
31	    /** Shown in place of a due when the grade has no rate. */
32	    private static final String NO_RATE = "n/a";
33	
34	    private final ClaimRepository claims;
35	    private final PersonRepository people;
36	    private final Dues dues;
37	    private final SheetService sheets;
38	    private final Rollups rollups;
39	    private final PeriodService periods;
40	    private final RoleService roles;
41	    private final WatchService watches;
42	    private final HolidayService holidays;
43	    private final VoidReasonService voidReasons;
44	    private final Audit audit;
45	
46	    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
47	            Rollups rollups, PeriodService periods, RoleService roles, WatchService watches, HolidayService holidays,
48	            VoidReasonService voidReasons, Audit audit) {
49	        this.watches = watches;
50	        this.holidays = holidays;
51	        this.voidReasons = voidReasons;
52	        this.periods = periods;
53	        this.roles = roles;
54	        this.claims = claims;
55	        this.people = people;
56	        this.dues = dues;
57	        this.sheets = sheets;
58	        this.rollups = rollups;
59	        this.audit = audit;
60	    }
61	
62	    /** A settle batch: its number, and the claims it settled, as they are now, in the order given. */
63	    public record Batch(int number, List<Claim> claims) {
64	    }
65	
66	    /**
67	     * Make the claims a bulk settle settled the sheet's next settle batch: each carries its number.
68	     * Audited as BATCH_SETTLED with the batch number, how many claims it holds, and the frozen figures
69	     * of those of them SETTLED, added up.
70	     */
71	    @Transactional
72	    public Batch batch(String sheetId, String user, List<Long> claimIds) {
73	        int number = sheets.lock(sheetId).nextSettleBatch();
74	        List<Claim> batched = new ArrayList<>();
75	        BigDecimal total = BigDecimal.ZERO;
76	        for (Long id : claimIds) {
77	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
78	            claim.settledInBatch(number);
79	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
80	                total = total.add(claim.getSettledDue());
81	            }
82	            batched.add(claims.save(claim));
83	        }
84	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number
85	                + " count=" + batched.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
86	        return new Batch(number, batched);
87	    }
88	
89	    /** The sheet's claims, newest first. */
90	    @Transactional(readOnly = true)
91	    public List<Claim> list(String sheetId) {
92	        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
93	    }
94	
95	    /**
96	     * Add a claim for a person on the sheet; with no date it is dated the sheet's entry date
97	     * while one is set, else the sheet's today. One dated or due by in a soft-closed period, or that would be
98	     * with the terms in force on the sheet's today, is a late entry, audited as LATE_ENTRY after its CLAIM_ADDED. Refused when
99	     * the due-by it would get (the terms-th business day after its date) is inside a closed period, or when it is a correction that does not name a SETTLED claim
100	     * of the same person (see {@link #refuseUnlessCorrects}).
101	     */
102	    @Transactional
103	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
104	            String corrects) {
105	        return add(sheetId, user, personId, amount, date, note, corrects, null);
106	    }
107	
108	    /**
109	     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String)}) with an
110	     * external reference (blank: none); refused when the reference is already used on the sheet, comparing
111	     * without regard to case. CLAIM_ADDED ends with ref=&lt;reference&gt; when one was given.
112	     */
113	    @Transactional
114	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
115	            String corrects, String ref) {
116	        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
117	    }
118	
119	    /**
120	     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)}) with
121	     * its tags, comma separated (see {@link Claim#tagsOf}). CLAIM_ADDED ends with tags=&lt;tags, sorted and
122	     * comma separated&gt; when any were given.
123	     */
124	    @Transactional
125	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
126	            String corrects, String ref, String tags) {
127	        Rollups.Rollup before = rollups.take(sheetId);
128	        Person person = person(sheetId, personId);
129	        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
130	        Sheet sheet = sheets.lock(sheetId);
131	        int terms = terms(sheet, person, dated);
132	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
133	        periods.refuseIfClosed(sheetId, dueBy);
134	        refuseIfRetired(person, dated);
135	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
136	        String referred = reference(ref);
137	        refuseIfReferred(sheetId, referred, null);
138	        Claim added = new Claim(sheetId, personId, money(amount), dated, terms, dueBy, clean(note), corrects);
139	        added.refer(referred);
140	        List<String> tagged = Claim.tagsOf(tags);
141	        added.tag(tagged);
142	        if (periods.softClosedOn(sheetId, dated) || periods.softClosedOn(sheetId, dueBy)
143	                || periods.softClosedOn(sheetId, holidays.dueBy(sheetId, dated, terms(sheet, person, sheet.getToday())))) {
144	            added.markLateEntry();
145	        }
146	        Claim claim = claims.saveAndFlush(added);
147	        claim = logged(claim, user, person);
148	        audited("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
149	                (referred != null ? " ref=" + referred : "")
150	                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
151	        if (claim.isLateEntry()) {
152	            audited("LATE_ENTRY", sheetId, user, person, claim);
153	        }
154	        rollups.audit(sheetId, user, before);
155	        return claim;
156	    }
157	
158	    /**
159	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
160	     * edited: an OPEN one is changed by voiding it and adding a new one. It keeps the due-by fixed when it
161	     * was added, and so its period. Refused when the claim's due-by, or the due-by a new date would give it
162	     * (the terms-th business day after it), is inside a closed period, or when it
163	     * would be a correction that does not name a SETTLED claim of the same person, or when its external
164	     * reference (null: kept as it is; blank: none) is already used by another claim on the sheet. Its tags
165	     * (null: kept as they are) are set from the comma separated text (see {@link Claim#tagsOf}).
166	     */
167	    @Transactional
168	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
169	            String corrects, String ref, String tags) {
170	        Rollups.Rollup before = rollups.take(sheetId);
171	        sheets.lock(sheetId);
172	        Claim claim = claim(sheetId, claimId);
173	        refuseUnlessEditable(sheetId, user, claim);
174	        if (date != null) {
175	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
176	            if (!date.equals(claim.getDate())) {
177	                periods.refuseIfClosed(sheetId, holidays.dueBy(sheetId, date, claim.getTerms()));
178	            }
179	        }
180	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
181	        String referred = ref == null ? claim.getRef() : reference(ref);
182	        refuseIfReferred(sheetId, referred, claim.getId());
183	        claim.refer(referred);
184	        if (tags != null) {
185	            claim.tag(Claim.tagsOf(tags));
186	        }
187	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
188	        claim.lockFor(null);
189	        claim.editedBy(user);
190	        Claim saved = claims.saveAndFlush(claim);
191	        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
192	        rollups.audit(sheetId, user, before);
193	        return saved;
194	    }
195	
196	    /**
197	     * Open a claim's editor for the user: the claim is locked for every other user until the editor is
198	     * saved or cancelled, or the sheet's today changes. Refused, taking no lock, when the claim cannot
199	     * be edited (see {@link #edit}) or another user's editor holds it.
200	     */
201	    @Transactional
202	    public Claim lock(String sheetId, String user, long claimId) {
203	        sheets.lock(sheetId);
204	        Claim claim = claim(sheetId, claimId);
205	        refuseUnlessEditable(sheetId, user, claim);
206	        claim.lockFor(user);
207	        return claims.saveAndFlush(claim);
208	    }
209	
210	    /** Cancel the user's editor of a claim, releasing its lock; a lock another user holds is left as it is. */
211	    @Transactional
212	    public Claim unlock(String sheetId, String user, long claimId) {
213	        sheets.lock(sheetId);
214	        Claim claim = claim(sheetId, claimId);
215	        if (user.equals(claim.getLockedBy())) {
216	            claim.lockFor(null);
217	            claim = claims.saveAndFlush(claim);
218	        }
219	        return claim;
220	    }
221	
222	    /** The sheet's today was changed: every editor's lock on its claims is released. */
223	    @EventListener
224	    public void todayChanged(TodayChanged change) {
225	        claims.unlockAll(change.sheetId());
226	    }
227	
228	    /**
229	     * Refuse an edit of a claim that is not a DRAFT, that is due by inside a closed period, or that
230	     * another user's editor holds (423).
231	     */
232	    private void refuseUnlessEditable(String sheetId, String user, Claim claim) {
233	        if (claim.getStatus() != ClaimStatus.DRAFT) {
234	            throw new ResponseStatusException(HttpStatus.CONFLICT,
235	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
236	        }
237	        periods.refuseIfClosed(sheetId, claim.getDueBy());
238	        if (claim.isLockedAgainst(user)) {
239	            throw new ResponseStatusException(HttpStatus.LOCKED,
240	                    "The claim is being edited by " + claim.getLockedBy() + ".");
241	        }
242	    }
243	
244	    /**
245	     * Move a claim to a new status, recording the event; refused (and nothing written) when the
246	     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
247	     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
248	     * with the late charge it has then frozen in.
249	     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
250	     * is never reused. The user who opened a claim,
251	     * or last edited it, is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
252	     * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
253	     * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
254	     * refused. A claim due by inside a closed period cannot be moved, nor can a claim
255	     * deferred on the sheet's today be settled. A SETTLED claim is voided only by a steward, within
256	     * {@link ClaimStatus#VOID_SETTLED_DAYS} days of its settlement; its frozen figure leaves every
257	     * total and the audit records it as reversed.
258	     */
259	    @Transactional
260	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
261	        return move(sheetId, user, claimId, next, null);
262	    }
263	
264	    /**
265	     * Move a claim as {@link #move(String, String, long, ClaimStatus)} does, voiding it with a reason:
266	     * while the sheet's list of void reasons is not empty, a void needs one from it (see
267	     * {@link VoidReasonService#require}); the claim keeps it and its audit record ends with it.
268	     */
269	    @Transactional
270	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason) {
271	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
272	        // sheet are serialised: each sees the other's committed claim and number.
273	        LocalDate today = sheets.lock(sheetId).getToday();
274	        Rollups.Rollup before = rollups.take(sheetId);
275	        Claim claim = claim(sheetId, claimId);
276	        periods.refuseIfClosed(sheetId, claim.getDueBy());
277	        String action = switch (next) {
278	            case OPEN -> "open";
279	            case SETTLED -> "settle";
280	            case VOID -> "void";
281	            case PENDING, DRAFT -> throw new IllegalArgumentException("No move to " + next + ".");
282	        };
283	        if (!roles.permits(sheetId, user, action)) {
284	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
285	        }
286	        if (!claim.getStatus().canBecome(next)) {
287	            throw new ResponseStatusException(HttpStatus.CONFLICT,
288	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
289	        }
290	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
291	        if (voidingSettled) {
292	            refuseVoidingSettled(sheetId, user, claim, today);
293	        }
294	        String voidReason = next == ClaimStatus.VOID ? voidReasons.require(sheetId, reason) : null;
295	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
296	            throw new ResponseStatusException(HttpStatus.CONFLICT,
297	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
298	        }
299	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
300	            throw new ResponseStatusException(HttpStatus.CONFLICT,
301	                    "The user who opened or last edited a claim cannot settle it.");
302	        }
303	        Person person = person(sheetId, claim.getPersonId());
304	        BigDecimal settledDue = next == ClaimStatus.SETTLED
305	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
306	                : null;
307	        if (next == ClaimStatus.OPEN) {
308	            refuseUnnoted(sheetId, claim, dues.due(claim, person.gradeOn(claim.getDate())));
309	        }
310	        if (next == ClaimStatus.SETTLED) {
311	            refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), settledDue);
312	        }
313	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
314	            next = ClaimStatus.PENDING;
315	            settledDue = null;
316	        }
317	        claim.become(next);
318	        if (next == ClaimStatus.OPEN) {
319	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
320	            claim.openedBy(user);
321	        }
322	        if (next == ClaimStatus.SETTLED) {
323	            claim.settleDue(settledDue);
324	        }
325	        if (next == ClaimStatus.VOID) {
326	            claim.voidedWith(voidReason);
327	        }
328	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
329	        String event = switch (next) {
330	            case OPEN -> "CLAIM_OPENED";
331	            case SETTLED -> "CLAIM_SETTLED";
332	            case PENDING -> "CLAIM_PENDING";
333	            case VOID -> "CLAIM_VOIDED";
334	            case DRAFT -> throw new IllegalStateException();
335	        };
336	        String suffix = next == ClaimStatus.SETTLED
337	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
338	                : voidingSettled
339	                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
340	                : "";
341	        if (voidReason != null) {
342	            suffix += " reason=" + voidReason;
343	        }
344	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
345	        if (next == ClaimStatus.SETTLED) {
346	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
347	        }
348	        rollups.audit(sheetId, user, before);
349	        return saved;
350	    }
