408	    /**
409	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it,
410	     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
411	     * statement. Refused when the claim is not OPEN, when the date is not after the sheet's today, or
412	     * when the claim is due by inside a closed period.
413	     */
414	    @Transactional
415	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
416	        LocalDate today = sheets.lock(sheetId).getToday();
417	        Rollups.Rollup before = rollups.take(sheetId);
418	        Claim claim = claim(sheetId, claimId);
419	        if (claim.getStatus() != ClaimStatus.OPEN) {
420	            throw new ResponseStatusException(HttpStatus.CONFLICT,
421	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
422	        }
423	        if (!until.isAfter(today)) {
424	            throw new ResponseStatusException(HttpStatus.CONFLICT,
425	                    "A claim can only be deferred to a date after the sheet's today, " + today + ".");
426	        }
427	        periods.refuseIfClosed(sheetId, claim.getDueBy());
428	        claim.defer(until);
429	        Claim saved = claims.saveAndFlush(claim);
430	        audited("CLAIM_DEFERRED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
431	                " until=" + until);
432	        rollups.audit(sheetId, user, before);
433	        return saved;
