436	    /**
437	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at this moment at its live figure with
438	     * the late charge it has then. Only a steward approves, and not the user who opened or last edited the claim.
439	     */
440	    @Transactional
441	    public Claim approve(String sheetId, String user, long claimId) {
442	        sheets.lock(sheetId);
443	        Rollups.Rollup before = rollups.take(sheetId);
444	        Claim claim = pending(sheetId, user, claimId);
445	        if (claim.isOpenedOrEditedBy(user)) {
446	            throw new ResponseStatusException(HttpStatus.CONFLICT,
447	                    "The user who opened or last edited a claim cannot approve it.");
448	        }
449	        Person person = person(sheetId, claim.getPersonId());
450	        BigDecimal approvedDue = dues.approving(claim, person.gradeOn(claim.getDate()));
451	        refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), approvedDue);
452	        claim.settleDue(approvedDue);
453	        claim.become(ClaimStatus.SETTLED);
454	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
455	        audited("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(),
456	                " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
457	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
458	        rollups.audit(sheetId, user, before);
459	        return saved;
460	    }
