463	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
464	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
465	     * re-settles; refused when the claim is not SETTLED or is due by inside a closed period.
466	     */
467	    @Transactional
468	    public Claim resettle(String sheetId, String user, long claimId) {
469	        sheets.lock(sheetId);
470	        Rollups.Rollup before = rollups.take(sheetId);
471	        Claim claim = claim(sheetId, claimId);
472	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
473	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
474	        }
475	        if (claim.getStatus() != ClaimStatus.SETTLED) {
476	            throw new ResponseStatusException(HttpStatus.CONFLICT,
477	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
478	        }
479	        periods.refuseIfClosed(sheetId, claim.getDueBy());
480	        Person person = person(sheetId, claim.getPersonId());
481	        BigDecimal old = claim.getSettledDue();
482	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
