484	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
485	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
486	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
487	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
488	        rollups.audit(sheetId, user, before);
