522	    /**
523	     * Reassign a claim as {@link #reassign(String, String, long, long)} does; when {@code toOwn} is set,
524	     * a claim already the new person's is not refused but reassigned to them again (as a bulk
525	     * reassign does to each selected claim).
526	     */
527	    @Transactional
528	    public Claim reassign(String sheetId, String user, long claimId, long personId, boolean toOwn) {
529	        sheets.lock(sheetId);
530	        Rollups.Rollup before = rollups.take(sheetId);
531	        Claim claim = claim(sheetId, claimId);
532	        if (!roles.permits(sheetId, user, "reassign")) {
533	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
534	        }
535	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
536	            throw new ResponseStatusException(HttpStatus.CONFLICT,
537	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
538	        }
539	        periods.refuseIfClosed(sheetId, claim.getDueBy());
540	        Person from = person(sheetId, claim.getPersonId());
541	        Person to = person(sheetId, personId);
542	        if (!toOwn && from.getId().equals(to.getId())) {
543	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
544	        }
545	        refuseIfRetired(to, claim.getDate());
546	        refuseUnlessCorrects(sheetId, personId, claim.getAmount(), claim.getCorrects());
547	        claim.reassign(to.getId());
548	        claim.unbind();
549	        if (claim.getNumber() != null) {
550	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
551	        }
552	        Claim saved = claims.saveAndFlush(claim);
553	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
554	                " from=" + from.getName() + " to=" + to.getName());
555	        rollups.audit(sheetId, user, before);
556	        return saved;
557	    }
