592	    /**
593	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
594	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
595	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
596	     * from the terms in force on its date, names the original's number as the one it was split from;
597	     * it is a late entry when that due-by is inside a soft-closed period. Refused when the claim is not
598	     * OPEN, is deferred on the sheet's today, or when its due-by or the new claim's is inside a closed
599	     * period.
600	     */
601	    @Transactional
602	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
603	        Sheet sheet = sheets.lock(sheetId);
604	        LocalDate today = sheet.getToday();
605	        Rollups.Rollup before = rollups.take(sheetId);
606	        Claim claim = claim(sheetId, claimId);
607	        if (claim.getStatus() != ClaimStatus.OPEN) {
608	            throw new ResponseStatusException(HttpStatus.CONFLICT,
609	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
610	        }
611	        if (claim.isDeferredOn(today)) {
612	            throw new ResponseStatusException(HttpStatus.CONFLICT,
613	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
614	        }
615	        periods.refuseIfClosed(sheetId, claim.getDueBy());
616	        BigDecimal off = money(amount);
617	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
618	            throw new ResponseStatusException(HttpStatus.CONFLICT,
619	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
620	        }
621	        Person person = person(sheetId, claim.getPersonId());
622	        int terms = terms(sheet, person, claim.getDate());
623	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
624	        periods.refuseIfClosed(sheetId, dueBy);
625	        Claim split = claim.split(off, terms, dueBy);
626	        if (periods.softClosedOn(sheetId, dueBy)) {
627	            split.markLateEntry();
628	        }
629	        split.number(periods.nextClaimNumber(sheetId, split.getDueBy()));
630	        split.openedBy(user);
631	        Claim original = claims.saveAndFlush(claim);
632	        split = logged(claims.saveAndFlush(split), user, person);
633	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
634	        audited("CLAIM_OPENED", sheetId, user, person, split);
635	        rollups.audit(sheetId, user, before);
636	        return new Split(original, split);
637	    }
