656	    /**
657	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
658	     * on the claim's date: its person's grade's (the grade in force then) when one is set, else the
659	     * sheet's (a due of n/a is within any threshold).
660	     */
661	    private void refuseUnproved(String sheetId, Claim claim, String grade, BigDecimal due) {
662	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
663	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
664	            throw new ResponseStatusException(HttpStatus.CONFLICT,
665	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
666	                            + ": it needs a proof before it is settled.");
667	        }
668	    }
