671	     * Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
672	     * on the claim's date (a due of n/a is within any threshold).
673	     */
674	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
675	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
676	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
677	                && due.compareTo(threshold) > 0) {
678	            throw new ResponseStatusException(HttpStatus.CONFLICT,
679	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
680	                            + ": it needs a note before it is opened.");
681	        }
682	    }
