685	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
686	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
687	     */
688	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
689	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
690	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
691	        }
692	        LocalDate settledOn = claim.settledOn();
693	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
694	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
695	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
696	        }
697	    }
