708	    /**
709	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
710	     * same person; and refuse naming a claim to correct on any other claim.
711	     */
712	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
713	        if (amount.signum() >= 0) {
714	            if (corrects != null) {
715	                throw new ResponseStatusException(HttpStatus.CONFLICT,
716	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
717	            }
718	            return;
719	        }
720	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
721	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
722	                .isPresent();
723	        if (!settled) {
724	            throw new ResponseStatusException(HttpStatus.CONFLICT,
725	                    "A correction must name the number of a SETTLED claim of the same person.");
726	        }
727	    }
