787	    /** Refuse a reference already used on the sheet by a claim other than the one given (null: any). */
788	    private void refuseIfReferred(String sheetId, String ref, Long self) {
789	        if (ref == null) {
790	            return;
791	        }
792	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
793	                .filter((other) -> !other.getId().equals(self))
794	                .ifPresent((other) -> {
795	                    throw new ResponseStatusException(HttpStatus.CONFLICT,
796	                            "The reference " + ref + " is already used on this sheet.");
797	                });
798	    }
799	
800	    /** A reference as typed, without surrounding spaces; null when blank. */
801	    static String reference(String ref) {
802	        return ref == null || ref.isBlank() ? null : ref.trim();
803	    }
804	
805	    private static BigDecimal money(BigDecimal amount) {
806	        return amount.setScale(2, RoundingMode.UNNECESSARY);
807	    }
808	
809	    private static String clean(String note) {
810	        return note == null ? "" : note.trim();
811	    }
812	}
