// open editor locks its claim for other users until it is saved or cancelled, and stays open across
// loads of the sheet),
// moved through their statuses (open, settle, approve, reject with a reason, void, re-settle) from each
// claim's row, deferred there until a date, split there into two, re-dated there, and reassigned there to another person.
const PAST: Record<ClaimAction, string> = {
  open: 'opened',
  settle: 'settled',
  approve: 'approved',
  reject: 'rejected',
  void: 'voided',
  resettle: 're-settled',
};

@Component({
  selector: 'app-claims',
  template: `
    <form (submit)="save($event)" [attr.aria-label]="(editing() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input
  return (claim.tags ?? []).join(', ');
}

/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED claims do. */
export function counts(claim: ClaimView): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** A claim's due-by (yyyy-mm-dd), fixed when it was added. */
export function dueBy(claim: ClaimView): string {
  return claim.dueBy;
import { Component, input } from '@angular/core';
import { StatusSummary } from '../summary/summary';

// The sheet's header: its counters, each repeating a figure shown elsewhere on the screen — the people
// on the sheet (retired people included), the summary's claim count per status, and the sheet's
// due-total and overdue-total.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Sheet counters">
      <p>People <strong data-testid="header-people-count">{{ peopleCount() }}</strong></p>
      <p>
        @for (s of statuses(); track s.status) {
          {{ s.status }} <strong [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</strong>
        }
      </p>
      <p>Due <strong data-testid="header-due-total">{{ dueTotal() }}</strong></p>
      <p>Overdue <strong data-testid="header-overdue-total">{{ overdueTotal() }}</strong></p>
    </header>
  `,
})
export class Header {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
}

